import test from 'node:test';
import assert from 'node:assert/strict';
import { createPublicKey, verify } from 'node:crypto';
import {
  COVERED_GET, COVERED_POST, SIGNATURE_ALGORITHM, SIGNATURE_TAG,
  signatureInput, signatureBase, signatureHeader, parseSignatureInput,
  parseSignatureHeader, contentDigest, parseContentDigest, jwkThumbprintSource
} from '../frontend/http-signatures.js';

// This is an INDEPENDENT published interoperability vector, not a signature
// generated by the KeyProve browser and verified by the KeyProve backend.
// Source: RFC 9421, Appendix B.1.3 and B.2.4 (response, ECDSA P-256).
test('RFC 9421 Appendix B.2.4 ECDSA P-256 signature base and official signature verify', () => {
  const base = signatureBase({
    components: ['@status', 'content-type', 'content-digest', 'content-length'],
    parameters: [['created', 1618884473], ['keyid', 'test-key-ecc-p256']],
    status: 200,
    fields: {
      'content-type': 'application/json',
      'content-digest': 'sha-512=:mEWXIS7MaLRuGgxOBdODa3xqM1XdEvxoYhvlCFJ41QJgJc4GTsPp29l5oGX69wWdXymyU0rjJuahq4l5aGgfLQ==:',
      'content-length': '23'
    }
  });
  const expected = [
    '"@status": 200',
    '"content-type": application/json',
    '"content-digest": sha-512=:mEWXIS7MaLRuGgxOBdODa3xqM1XdEvxoYhvlCFJ41QJgJc4GTsPp29l5oGX69wWdXymyU0rjJuahq4l5aGgfLQ==:',
    '"content-length": 23',
    '"@signature-params": ("@status" "content-type" "content-digest" "content-length");created=1618884473;keyid="test-key-ecc-p256"'
  ].join('\n');
  assert.equal(base, expected);
  const publicKey = createPublicKey(`-----BEGIN PUBLIC KEY-----
MFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEqIVYZVLCrPZHGHjP17CTW0/+D9Lf
w0EkjqF7xB4FivAxzic30tMM4GF+hR6Dxh71Z50VGGdldkkDXZCnTNnoXQ==
-----END PUBLIC KEY-----`);
  const publishedSig = 'wNmSUAhwb5LxtOtOpNa6W5xj067m5hFrj0XQ4fvpaCLx0NKocgPquLgyahnzDnDAUy5eCdlYUEkLIj+32oiasw==';
  assert.equal(verify('sha256', Buffer.from(base, 'ascii'),
    { key: publicKey, dsaEncoding: 'ieee-p1363' }, Buffer.from(publishedSig, 'base64')), true);
});

test('Structured Fields signature metadata parses and preserves metadata order', () => {
  const params = [['keyid', 'jwk-sha256-key'], ['nonce', 'nonce'], ['tag', SIGNATURE_TAG],
    ['alg', SIGNATURE_ALGORITHM], ['created', 1618884473]];
  const input = signatureInput(COVERED_POST, params);
  assert.equal(input, 'sig1=("@method" "@target-uri" "content-type" "content-digest");keyid="jwk-sha256-key";nonce="nonce";tag="keyprove-v1";alg="ecdsa-p256-sha256";created=1618884473');
  const parsed = parseSignatureInput(input);
  assert.deepEqual(parsed.components, COVERED_POST);
  assert.deepEqual(parsed.parameters, params);
  assert.equal(parsed.metadata.nonce, 'nonce');
  const base = signatureBase({
    components: parsed.components, parameters: parsed.parameters,
    method: 'POST', targetUri: 'https://example.com/api/private/notes?sort=asc',
    fields: { 'content-type': 'application/json', 'content-digest': contentDigest(Buffer.alloc(32).toString('base64')) }
  });
  assert.equal(base.split('\n').at(-1), '"@signature-params": ' + input.slice('sig1='.length));
});

test('RFC 9421 rejects duplicate components, malformed SF values and incomplete metadata', () => {
  const base = signatureInput(COVERED_GET, [
    ['created', 1618884473], ['nonce', 'abc'], ['keyid', 'key'],
    ['alg', SIGNATURE_ALGORITHM], ['tag', SIGNATURE_TAG]
  ]);
  assert.equal(parseSignatureInput(base).components.length, 2);
  for (const value of [
    base.replace('"@target-uri"', '"@method"'),
    base.replace('"@target-uri"', '"@target-uri";sf'),
    base.replace('"@method" "@target-uri"', '"@method", "@target-uri"'),
    base.replace(';created=1618884473', ''),
    base + ';nonce="duplicate"',
    base.replace('keyprove-v1', 'bad\\q'),
    base + ',sig2=("@method")',
    'sig1=("@method" "@target-uri");created=1;nonce="a";keyid="x";alg="y";tag="z";created=2'
  ]) assert.throws(() => parseSignatureInput(value), /Invalid HTTP signature/);
  assert.throws(() => signatureBase({
    components: COVERED_GET, parameters: [], method: 'GET', targetUri: 'https://example.com/\nspoof'
  }));
  assert.throws(() => signatureInput(['@method', '@method'], []));
});

test('RFC 9530 Content-Digest and RFC 9421 Signature are Structured Field values', () => {
  const value = Buffer.from('abc').toString('base64');
  assert.equal(signatureHeader(value), `sig1=:${value}:`);
  const raw = Buffer.alloc(64, 42).toString('base64');
  assert.equal(parseSignatureHeader(signatureHeader(raw)), raw);
  assert.throws(() => parseSignatureHeader('sig1=:' + raw.slice(0, 85) + ':'));
  assert.throws(() => parseSignatureHeader('sig1=:' + raw + ':,sig2=:' + raw + ':'));
  const digest = Buffer.alloc(32, 43).toString('base64');
  assert.equal(parseContentDigest(contentDigest(digest)), digest);
  assert.throws(() => parseContentDigest('sha-256=:' + digest + ':,sha-512=:bad:'));
  assert.throws(() => contentDigest('not-base64!'));
  assert.equal(jwkThumbprintSource({ crv: 'P-256', kty: 'EC', x: 'a', y: 'b' }),
    '{"crv":"P-256","kty":"EC","x":"a","y":"b"}');
});
